<?php
if(!isset($user)){http_response_code(403);exit;}
require_once APP_ROOT.'/app/helpers/careers.php';if(!career_can($user)){return;}
if(!employment_ready()){echo '<p class="notice">Rekap hasil alumni tersedia setelah pembaruan database 024 diterapkan.</p>';return;}
$careerYear=input_text($_GET,'career_year');if($careerYear!==''&&!preg_match('/^[0-9]{4}$/D',$careerYear)){http_response_code(400);exit('Tahun alumni tidak valid.');}
$careerData=career_dashboard($careerYear);$careerPages=max(1,(int)ceil(count($careerData['rows'])/20));$careerPage=min($careerPages,positive_id($_GET['career_page']??'1')??1);$careerRows=array_slice($careerData['rows'],($careerPage-1)*20,20);
$careerYears=panel_query('SELECT DISTINCT tahun_lulus FROM tracer_responses ORDER BY tahun_lulus DESC')->fetchAll(PDO::FETCH_COLUMN);
?>
<section id="career-results"><div class="page-actions"><h2>Hasil seleksi dan keterserapan alumni</h2><a href="<?= e(base_url('panel/hasil-alumni/lamaran.php')) ?>">Catat / kelola lamaran alumni</a></div>
<form class="filter-form card" method="get"><label>Tahun lulus<select name="career_year"><option value="">Semua tahun</option><?php foreach($careerYears as $year): ?><option value="<?= (int)$year ?>" <?= (string)$year===$careerYear?'selected':'' ?>><?= (int)$year ?></option><?php endforeach; ?></select></label><button>Tampilkan rekap</button></form>
<div class="summary-grid"><section class="card"><h3>Alumni tercatat</h3><strong><?= $careerData['total'] ?></strong></section><section class="card"><h3>Sudah mulai bekerja</h3><strong><?= $careerData['working'] ?></strong><p><?= e((string)$careerData['percentage']) ?>% dari alumni tercatat</p></section><section class="card"><h3>Lolos seleksi</h3><strong><?= $careerData['passed'] ?></strong><p>Alumni yang pernah melaporkan Lolos. Tidak otomatis dihitung sudah bekerja.</p></section></div>
<p>Alumni dihitung unik berdasarkan NISN yang terisi; tanpa NISN dihitung per catatan tracer. Keterserapan memerlukan laporan sudah mulai bekerja, tanggal mulai tidak mendatang, serta perusahaan, posisi, dan jenis hubungan kerja lengkap. Data tracer lama tanpa rincian ini belum dihitung terserap.</p>
<div class="table-scroll"><table><thead><tr><th>Alumni / jurusan / tahun</th><th>Hasil seleksi per lamaran</th><th>Status kerja terakhir dilaporkan</th><th>Tindakan</th></tr></thead><tbody><?php foreach($careerRows as $family):$person=$family['person']; ?><tr><td><?= e($person['nama_lengkap']) ?><br><?= e($person['jurusan']) ?><br><?= (int)$person['tahun_lulus'] ?></td><td><?php if(!$family['applications']): ?>Belum Mengisi — belum ada catatan lamaran<?php else: ?><ul><?php foreach($family['applications'] as $application): ?><li><?= e($application['posisi'].' — '.$application['perusahaan']) ?>: <strong><?= e(career_result_label($application)) ?></strong><?= $application['seleksi_selesai']?' (seleksi selesai)':'' ?> <a href="<?= e(base_url('panel/hasil-alumni/lamaran.php?tracer_id='.$application['tracer_id'])) ?>">Kelola</a></li><?php endforeach; ?></ul><?php endif; ?></td><td><?php if($family['started']): ?>Sudah mulai bekerja<br><?= e($family['work']['perusahaan'].' — '.$family['work']['posisi']) ?><br><?= e($family['work']['tanggal_mulai'].' — '.$family['work']['jenis']) ?><?php else: ?>Belum tercatat sudah mulai bekerja<?php endif; ?></td><td><a href="<?= e(base_url('panel/hasil-alumni/lamaran.php?tracer_id='.$person['id'])) ?>">Lamaran / tautan alumni</a></td></tr><?php endforeach; ?><?php if(!$careerRows): ?><tr><td colspan="4">Belum ada alumni untuk pilihan ini.</td></tr><?php endif; ?></tbody></table></div>
<nav class="pagination" aria-label="Halaman hasil alumni"><?php foreach(['Sebelumnya'=>$careerPage-1,'Berikutnya'=>$careerPage+1] as $label=>$target):if($target<1||$target>$careerPages){continue;} ?><a href="<?= e('?'.http_build_query(['career_year'=>$careerYear,'career_page'=>$target]).'#career-results') ?>"><?= $label ?></a><?php endforeach; ?></nav></section>
